import sys, zipfile, re
from pathlib import Path
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

def col_number(ref):
    m = re.match(r"([A-Z]+)", ref or "")
    if not m:
        return 0
    n = 0
    for ch in m.group(1):
        n = n * 26 + (ord(ch) - 64)
    return n

def read_xlsx(path):
    with zipfile.ZipFile(path) as z:
        shared = []
        if "xl/sharedStrings.xml" in z.namelist():
            root = ET.fromstring(z.read("xl/sharedStrings.xml"))
            for si in root.findall("m:si", NS):
                shared.append("".join(t.text or "" for t in si.iter("{%s}t" % NS["m"])))
        sheets = sorted(n for n in z.namelist() if n.startswith("xl/worksheets/sheet") and n.endswith(".xml"))
        if not sheets:
            return []
        root = ET.fromstring(z.read(sheets[0]))
        rows = []
        for row in root.findall(".//m:row", NS):
            cells = {}
            for cell in row.findall("m:c", NS):
                idx = col_number(cell.attrib.get("r", ""))
                typ = cell.attrib.get("t")
                if typ == "inlineStr":
                    val = "".join(t.text or "" for t in cell.iter("{%s}t" % NS["m"]))
                else:
                    v = cell.find("m:v", NS)
                    val = v.text if v is not None and v.text is not None else ""
                    if typ == "s" and val != "":
                        val = shared[int(val)]
                    elif typ == "b":
                        val = "True" if val == "1" else "False"
                cells[idx] = val
            width = max(cells.keys(), default=0)
            rows.append([cells.get(i, "") for i in range(1, width + 1)])
        return rows

