    paths = sorted(p for p in root.rglob("*") if p.is_file())
else:
    try:
        lines = root.read_text().splitlines()
    except Exception:
        lines = []
    referenced = []
    for line in lines:
        bits = line.split("\t")
        for bit in reversed(bits):
            p = Path(bit)
            if p.is_file():
                referenced.append(p)
                break
    paths = referenced if referenced else [root]

with open("merged.tsv", "w", encoding="utf-8") as out:
